const P0="D:\\GitHub\\My-second-brain";
const m1="接单平台落地工具：可导入Chrome的70个书签文件+每日巡检表";
const m2=`目标要求可同时关注多个平台有活就干。除70个平台清单外，追加两份可直接使用的落地工具。

工具1 接单平台书签-70个.html：Netscape书签格式可直接导入Chrome/Edge/Firefox，70个链接按14类分好文件夹，每个书签前面标注[A]或[B]级别。导入方法：Chrome右上角三点→书签→书签管理器→右上角三点→导入书签→选这个文件→书签栏出现接单平台70个文件夹。已验证格式正确70个链接15个文件夹DOCTYPE正确。

工具2 接单平台每日巡检表.md：70个平台按活更新速度分三档。每天必看20个（Freelancer/Upwork/PeoplePerHour/Toptal/Fiverr/Dribbble/Prolific/Userfeel/Userlytics/Validately/UsabilityHub/UserZoom/TestingTime/PlaytestCloud/Clickworker/OneForma/FigureEight/Microworkers/Toloka/Remotasks）活更新最快前5个看完就够本；每周看2-3次22个（转录全部加翻译全部加写作全部加中文接单全部）活更新较慢；每周看1次33个（家教加赏金加AI训练加专家咨询加设计加实地）要审核或竞争大。附记录表每接一单记一行记日期平台什么活报价状态到账，做10单之后就能看出哪个平台值得留。

前两周目标：第1周注册完每天20个都有账号、至少投接3单不管钱多少；第2周有1单成交证明路是通的、淘汰掉5个没活的平台减少无效巡检。关键不是接多少是验证这套流程走不走得通。

用法建议：早上15分钟扫每天那20个看有没有新活、周一周四扫每周那22个、周末扫每周看1次那33个挑着投、有活立刻投不管钱多少先做一单。别贪多一天15分钟足够了扫完该干嘛干嘛。`;

const r = await tools.pwsh({
  description:"commit bookmarks and routine",
  command:`cd "${P0}"; git -c http.proxy=http://127.0.0.1:7897 -c https.proxy=http://127.0.0.1:7897 add -A; git -c http.proxy=http://127.0.0.1:7897 -c https.proxy=http://127.0.0.1:7897 commit -m "${m1}" -m "${m2}"; git -c http.proxy=http://127.0.0.1:7897 -c https.proxy=http://127.0.0.1:7897 push origin main`,
  timeoutMs:180000
});
return { out: String((r.kind==='foreground'?r.stdout.text+r.stderr.text:r.output)||"").trim().slice(-130) };
